pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 lockTime, uint256 minSum, uint128 collectAmt, uint128 depositAmt) public {
        // Bound to avoid overflow in arithmetic (wide domain)
        lockTime = bound(lockTime, 0, type(uint256).max - block.timestamp);
        minSum = bound(minSum, 0, type(uint256).max);
        collectAmt = uint128(bound(uint256(collectAmt), 0, type(uint128).max));
        depositAmt = uint128(bound(uint256(depositAmt), 1, type(uint128).max));

        // Step 1: Initialize the contract
        vm.prank(address(0x1));
        c.Initialized();
        // Step 2: Setup LogFile (just a dummy address to satisfy existing code, but LogFile is not strictly needed)
        vm.prank(address(0x1));
        c.SetLogFile(address(0x2));
        // Step 3: Set MinSum to a known initial value
        vm.prank(address(0x1));
        c.SetMinSum(minSum);

        uint256 initMinSum = c.MinSum();

        // Step 4: Deploy a reentrant attacker that will try to call SetMinSum during Collect
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), minSum);

        // Step 5: Deposit into C from the attacker's address
        vm.deal(address(attacker), uint256(depositAmt) + 1 ether); // extra for gas
        vm.prank(address(attacker));
        c.Put{value: depositAmt}(lockTime);

        // Step 6: Warp past unlock time so that Collect can happen
        vm.warp(block.timestamp + lockTime + 1);

        // Step 7: Trigger the reentrant call via Collect
        vm.prank(address(attacker));
        attacker.attack(collectAmt);

        // After the call, check that MinSum remained unchanged in the reference contract
        // In the buggy version, MinSum will be changed to 0 by the reentrant SetMinSum call.
        assertTrue(c.MinSum() == initMinSum);
    }
}

// Minimal reentrant attacker: during receive (which is triggered by the low-level call in Collect),
// it attempts to call SetMinSum(0) on the target C. Since the buggy version lacks the nonReentrant modifier,
// this reentrant call succeeds and changes MinSum.
contract ReentrantAttacker {
    C public target;
    uint256 public newMinSum;
    bool private attacking;

    constructor(address _target, uint256 _newMinSum) {
        target = C(_target);
        newMinSum = _newMinSum;
    }

    function attack(uint256 amt) external payable {
        attacking = true;
        target.Collect(amt);
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Reentrantly call SetMinSum with a different value (0)
            // In the reference version, this will fail due to nonReentrant modifier.
            // In the buggy version, this succeeds and changes MinSum.
            target.SetMinSum(newMinSum);
        }
    }
}

