pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 setMinSumValue, address caller, uint256 lockTime, uint256 initialDeposit, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(initialDeposit >= collectAmount);
        vm.assume(collectAmount > 0);
        vm.assume(setMinSumValue > 0);
        vm.assume(lockTime < block.timestamp + 365 days);

        // initialize contract first
        vm.startPrank(caller);
        c.Initialized();
        vm.stopPrank();

        // set MinSum to some initial value (via public access, here we use a fuzzed value)
        vm.prank(caller);
        c.SetMinSum(setMinSumValue);

        // deposit
        vm.deal(caller, initialDeposit);
        vm.startPrank(caller);
        c.Put{value: initialDeposit}(lockTime);
        vm.stopPrank();

        // unlock time must pass
        vm.warp(block.timestamp + lockTime + 1);

        // record MinSum before any mutation
        uint256 minSumBefore = c.MinSum();
        bool collectSucceededBefore;
        vm.prank(caller);
        try c.Collect(collectAmount) { collectSucceededBefore = true; } catch { collectSucceededBefore = false; }

        // roll back state (we can't easily revert the Collect effect, but we can redeploy, or we note that the invariant is about the dependency of Collect on MinSum changes)
        // Instead, deploy a fresh instance to check after mutation
        C c2 = new C();
        vm.startPrank(caller);
        c2.Initialized();
        c2.SetMinSum(setMinSumValue);
        vm.stopPrank();
        vm.deal(caller, initialDeposit);
        vm.startPrank(caller);
        c2.Put{value: initialDeposit}(lockTime);
        vm.stopPrank();
        vm.warp(block.timestamp + lockTime + 1);

        // now change MinSum on the buggy contract
        vm.prank(caller);
        // on the reference contract, this would revert after initialization, but we test c (reference) behavior via try/catch
        // We call SetMinSum on c (reference) and expect it to revert, so MinSum should stay the same
        try c.SetMinSum(0) { } catch { }

        // On c, MinSum must remain unchanged after SetMinSum(0) because it reverts, thus Collect outcome for same caller state must be identical to before
        // Actually, we need to guarantee that SetMinSum cannot change MinSum after init, so Collect outcome is invariant regardless of attempts to change MinSum.
        // The property: after initialization, for any Collect call with given caller state, the success/revert result is the same as if SetMinSum(0) had been called (which does nothing on reference).
        // We assert that try/catch result of SetMinSum(0) does not alter the outcome of a subsequent identical Collect.
        bool collectSucceededAfter;
        vm.prank(caller);
        try c.Collect(collectAmount) { collectSucceededAfter = true; } catch { collectSucceededAfter = false; }

        assertTrue(collectSucceededBefore == collectSucceededAfter);
    }
}

