        vm.assume(deposit >= minSum);
        vm.assume(collectAmt > 0 && collectAmt <= deposit);
        vm.assume(lockTime < type(uint256).max - block.timestamp);

        // Deploy a re-entrant attacker that tries to reset MinSum on collect callback
        ReentrantAttacker helper = new ReentrantAttacker();
        address helperAddr = address(helper);

        // Initialize the contract and set MinSum
        c.Initialized();
        c.SetMinSum(minSum);

        // Fund attacker EOA
        vm.deal(attacker, deposit + lockTime);

        // Have attacker put deposit with lockTime
        vm.startPrank(attacker);
        c.Put{value: deposit}(lockTime);
        vm.stopPrank();

        // Record pre-collect MinSum
        uint256 preMinSum = c.MinSum();

        // Warp past unlock time so Collect is allowed
        (, uint256 unlock) = c.Acc(attacker);
        vm.warp(unlock + 1);

        // Attacker's collect attempt using the re-entrant helper as the caller;
        // the helper's receive() will call SetMinSum(0) on c.
        helper.setTarget(address(c));
        vm.deal(helperAddr, 0);
        vm.prank(helperAddr);
        // helper calls Collect; if Collect sends ETH back, helper's receive triggers re-entrancy
        c.Collect(collectAmt);

        // After the call, MinSum should NOT have changed in the correct version.
        uint256 postMinSum = c.MinSum();
        assertTrue(postMinSum == preMinSum);
    }
}

